function withQuery(path: string, query: Record<string, string | number | boolean>): string {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    params.set(key, String(value));
  });
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

export async function listPntReceipts(
  query: Record<string, string | number | boolean>,
): Promise<PntReceiptListItem[]> {
  const res = await apiClient.get<BffResponse<PntReceiptListItem[]>>(withQuery(BASE, query));
  return unwrap(res);
}

export async function getPntReceipt(sttRec: string): Promise<PntReceipt> {
  const res = await apiClient.get<BffResponse<PntReceipt>>(`${BASE}/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function createPntReceipt(body: PntReceiptWrite): Promise<PntReceipt> {
  const res = await apiClient.post<BffResponse<PntReceipt>>(BASE, body);
  return unwrap(res);
}

export async function updatePntReceipt(sttRec: string, body: PntReceiptWrite): Promise<PntReceipt> {
  const res = await apiClient.put<BffResponse<PntReceipt>>(`${BASE}/${encodeURIComponent(sttRec)}`, body);
  return unwrap(res);
}

export interface ToolEquipmentHit {
  code: string;
  name: string;
  unit: string;
}

export async function listToolsEquipment(search: string): Promise<ToolEquipmentHit[]> {
  const res = await apiClient.get<BffResponse<{ items: ToolEquipmentHit[] }>>(
    `/master/tools-equipment?search=${encodeURIComponent(search)}&page=1&pageSize=20`,
  );
  return unwrap(res).items ?? [];
}
